    sqRec (k + 1) v =
      let sh := UInt64.ofNat (2 ^ k)
      let m := ((1 : UInt64) <<< sh) - 1
      let s0 := sqRec k (v &&& m)
      let s1 := sqRec k (v >>> sh)
      ((mulByZRec k s1) <<< sh) ||| (s0 ^^^ s1)

